const imagensTransito = [
    { nome: "Proibido Ultrapassar", url: "data:image/png;base64," },
    { nome: "Vire a Direita", url: "data:image/png;base64," },
    { nome: "Vire a Esquerda", url: "data:image/png;base64," },
    { nome: "Cruzamneto de Via", url: "data:image/jpeg;base64," },
    { nome: "Placa Pare", url: "https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/Brasil_R-1.svg/2048px-Brasil_R-1.svg.png" },
    { nome: "Proibido Estacionar", url: "data:image/png;base64," },
    { nome: "Velocidade Maxíma", url: "data:image/png;base64," },
    { nome: "Curva Acentuada", url: "data:image/jpeg;base64," }
  ];
  
  let fase = 1;
  let primeiraCarta = null;
  let segundaCarta = null;
  let bloqueia = false;
  let paresEncontrados = 0;
  
  const board = document.getElementById("game-board");
  const faseTexto = document.getElementById("fase");
  const mensagem = document.getElementById("mensagem");
  const btnNext = document.getElementById("btn-next");
  const btnReset = document.getElementById("btn-reset");
  
  function iniciarFase() {
    const qtdPares = fase * 2;
    const imagensSelecionadas = imagensTransito.slice(0, qtdPares);
    const cartas = [...imagensSelecionadas, ...imagensSelecionadas].sort(() => Math.random() - 0.5);
  
    board.innerHTML = "";
    paresEncontrados = 0;
    faseTexto.textContent = `Fase ${fase}`;
    mensagem.textContent = "";
  
    const colunas = Math.min(qtdPares * 2, 4);
    board.style.gridTemplateColumns = `repeat(${colunas}, 110px)`;
  
    cartas.forEach((imgInfo) => {
      const card = document.createElement("div");
      card.classList.add("card");
      card.dataset.nome = imgInfo.nome;
  
      const inner = document.createElement("div");
      inner.classList.add("card-inner");
  
      const front = document.createElement("div");
      front.classList.add("card-front");
      front.textContent = "❓";
  
      const back = document.createElement("div");
      back.classList.add("card-back");
      const img = document.createElement("img");
      img.src = imgInfo.url;
      back.appendChild(img);
  
      inner.appendChild(front);
      inner.appendChild(back);
      card.appendChild(inner);
  
      card.addEventListener("click", () => virarCarta(card));
      board.appendChild(card);
    });
  }
  
  function virarCarta(carta) {
    if (bloqueia || carta.classList.contains("flipped")) return;
  
    carta.classList.add("flipped");
  
    if (!primeiraCarta) {
      primeiraCarta = carta;
    } else {
      segundaCarta = carta;
      bloqueia = true;
  
      if (primeiraCarta.dataset.nome === segundaCarta.dataset.nome) {
        mensagem.textContent = "✅ Par encontrado!";
        paresEncontrados++;
        resetarSelecao();
  
        if (paresEncontrados === fase * 2) {
          mensagem.textContent = `🎉 Fase ${fase} concluída!`;
        }
      } else {
        mensagem.textContent = "❌ Tente novamente...";
        setTimeout(() => {
          primeiraCarta.classList.remove("flipped");
          segundaCarta.classList.remove("flipped");
          resetarSelecao();
        }, 1000);
      }
    }
  }
  
  function resetarSelecao() {
    primeiraCarta = null;
    segundaCarta = null;
    bloqueia = false;
  }
  
  btnNext.addEventListener("click", () => {
    if (fase < 3) {
      fase++;
      iniciarFase();
    } else {
      mensagem.textContent = "🏁 Você completou todas as fases!";
    }
  });
  
  btnReset.addEventListener("click", () => {
    fase = 1;
    iniciarFase();
  });
  
  iniciarFase();
  